const messages = $input.all()
  .map(i => i.json.msg_blocage)
  .filter(Boolean);

const unique = [...new Set(messages)];

const texte =
  `*Blocages du ${$now.toFormat('dd/MM/yyyy')}*\n\n` +
  unique.map((m, idx) => `${idx + 1}. ${m}`).join('\n');

return [{
  json: {
    to: "+212652060652",   // numéro au format international, sans + ni espaces
    texte,
    nb_messages: unique.length,
  },
}];

const groupes = {};

for (const item of $input.all()) {
  const { FactureFrns, Bon_Reception } = item.json;

  if (!groupes[FactureFrns]) {
    groupes[FactureFrns] = new Set();
  }
  groupes[FactureFrns].add(Bon_Reception);
}

return Object.entries(groupes).map(([FactureFrns, brs]) => {
  const liste = [...brs];

  return {
    json: {
      msg_blocage: `Ecart facture et réception : ${FactureFrns}, ${liste.join(', ')} `,
    },
  };
});
